function replyHandoffPush(turn,list,...items){if(turn&&turn.claimed)items.forEach(m=>{if(m&&m.role==='assistant'){m._replyToUserId=turn.messageId;m._replyToAccountId=turn.aid;}});return list.push(...items);}
