async function roleServerPushTestPoll(id,taskId,show){if(!taskId||document.hidden)return false;const data=await roleBackgroundTaskStatus(id,taskId);if(!data.ok){if(show)toast('后台测试状态暂时无法读取：'+String(data.error||''),5000);return false;}const row=_roleServerPushTestJobs[id]||(_roleServerPushTestJobs[id]={});Object.assign(row,{taskId,data,checkedAt:Date.now()});if(data.pushStatus==='sent'){delete _roleServerPushTestJobs[id];const pulled=await roleServerPushPull(true);toast(pulled?'后台测试成功：通知与真实聊天消息已同步':'APNs 已被 Apple 接受；聊天消息将在回到小手机后继续补拉',7000);return true;}if(data.taskStatus==='failed'||data.taskStatus==='canceled'){delete _roleServerPushTestJobs[id];roleBackgroundShowFailure('后台测试没有送达',[roleBackgroundTaskFailureText(data)]);return false;}if(show)toast(data.taskStatus==='claimed'?'服务器正在调用当前模型生成…':'真实任务已入库，等待服务器处理',5000);return null;}
