/* 限流要等久一点再试，立刻重发只会再吃一次 429。 */
function roleTextTranslationBackoff(error,attempt){const status=Number(error&&error.status)||0,text=String(error&&error.message||error||''),limited=status===429||/rate.?limit|限流|请求太多/i.test(text);return (limited?[2500,6000]:[650,1500])[attempt]||6000;}
function roleTextTranslationFailureLabel(error){const status=Number(error&&error.status)||0,text=String(error&&error.message||error||'');if(status===401||status===403||/鉴权|unauthor|forbidden|api.?key|invalid.?key/i.test(text))return'翻译鉴权失败，请检查副模型 Key';if(status===402||/no.?balance|余额不足|点数不足|额度不足|insufficient.?quota/i.test(text))return'翻译额度不足';if(status===429||/rate.?limit|限流|请求太多/i.test(text))return'翻译请求太多';if(status===408||/timeout|超时/i.test(text))return'翻译请求超时';if(status>=500||/network|fetch|connection|temporar|网络|连接/i.test(text))return'翻译服务暂时不可用';if(/结果为空|返回为空/i.test(text))return'翻译返回为空';return'翻译暂时失败';}
async function roleTextTranslationRun(jobs){const live=[];for(const j of jobs||[]){const m=msgs(j.cid).find(x=>x.id===j.mid);if(getC(j.cid)&&m&&String(m.content||'').trim()===j.source){j.m=m;live.push(j);}else _roleTextTranslationBusy.delete(j.key);}if(!live.length)return;const cid=live[0].cid,c=getC(cid);
  try{const routeIndex=typeof roleChatRouteIndex==='function'?roleChatRouteIndex(c):undefined;
    const ask=async list=>{const sources=list.map(j=>j.source),total=sources.reduce((n,x)=>n+x.length,0),single=list.length===1;let lastError=null;for(let attempt=0;attempt<3;attempt++){try{const raw=await chatAPI(single?roleTextTranslationPrompt(sources[0]):roleTextTranslationBatchPrompt(sources),{aux:true,routeIndex,temp:.1,max:Math.max(320,Math.min(2400,Math.ceil(total*2.2)+list.length*24)),timeout:90000,complete:true,roleInterceptAudit:null,roleInterceptStage:'微信文字自动翻译'}),parts=single?[roleTextTranslationClean(raw)]:roleTextTranslationBatchParse(raw,list.length);if(!parts.some(Boolean))throw new Error('翻译结果为空');return parts;}catch(error){lastError=error;if(attempt<2&&roleTextTranslationRetryable(error)){await sleep(roleTextTranslationBackoff(error,attempt));continue;}throw error;}}throw lastError||new Error('翻译结果为空');};
    const apply=(list,parts)=>list.filter((j,i)=>{const out=parts[i],m=j.m,source=j.source;if(!out)return true;if(String(m.content||'').trim()===source){m.textTrans=out;m.textTransSource=source;m._textTransState='done';delete m._textTransError;delete m._textTransLabel;}j.done=true;return false;});
    let missing=apply(live,await ask(live));
    /* 模型漏了个别编号：只把漏掉的那几条再合并问一次，不退回一条一条地问。 */
    if(missing.length&&missing.length<live.length)missing=apply(missing,await ask(missing));
    if(missing.length)throw new Error('翻译结果为空');save();}
  catch(e){live.forEach(j=>{if(j.done)return;const m=j.m;if(String(m.content||'').trim()===j.source){m._textTransState='failed';m._textTransError=String(e&&e.message||'翻译失败').slice(0,120);m._textTransLabel=roleTextTranslationFailureLabel(e);}});if(live.some(j=>j.done))save();}
  finally{live.forEach(j=>_roleTextTranslationBusy.delete(j.key));(typeof roleTextTranslationPatch==='function'?roleTextTranslationPatch(cid,live.map(j=>j.m)):cur().p==='chat'&&cur().id===cid&&refreshChatMessages(cid));}}
